const path="/Users/anudeepbonagiri/dev/hackathons/dispatch-ledger/seed/fixtures/evidence/telematics/77.csv";
const data=await tools.Read({file_path:path});
if(typeof data!=="string") throw new Error("Expected CSV text");
const rows=data.trim().split("\n");
const truck3=rows.map((line,i)=>({line:i+1,text:line})).filter(r=>r.text.startsWith("3,"));
text({source:"telematics/77.csv",truck3});
const rad=d=>d*Math.PI/180;
const within=rows.slice(1).map((line,i)=>{const [truck,at,lat,lon]=line.split(",");const a=Math.sin(rad(Number(lat)-28.3053)/2)**2+Math.cos(rad(28.3053))*Math.cos(rad(Number(lat)))*Math.sin(rad(Number(lon)+97.2753)/2)**2;return {line:i+2,text:line,at,distance_m:6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))};}).filter(r=>r.at>="2026-10-15T15:05:14Z"&&r.at<="2026-10-15T15:25:14Z");
text({source:"telematics/77.csv",local_window_has_pings:within.length>0,local_window_pings_within_3000m:within.filter(r=>r.distance_m<=3000)});
